ROWS = [
dict(id="T051", d="SM", t="Full replica symmetry breaking in the Sherrington–Kirkpatrick model",
 s="For the SK model with no external field at inverse temperature β > 1, the Parisi measure (the unique minimiser in the Parisi formula) is full-RSB: its support is an interval [0, q_*] and it has an absolutely continuous part, rather than finitely many atoms.",
 src="G. Parisi, A sequence of approximated solutions to the S-K model for spin glasses, J. Phys. A 13 (1980); M. Talagrand, Mean Field Models for Spin Glasses, Vol. II (Springer, 2011)",
 why="Full RSB is the central prediction of Parisi's theory beyond the free energy, and at zero temperature it implies the no-overlap-gap property that makes near-optimal ground states findable in polynomial time (Montanari 2019).",
 st="Proved: Lopatto (arXiv:2607.11756, v4), for zero external field and every β > 1, with Zhou (arXiv:2504.00269) first just past the critical temperature. Before that: the Parisi formula (Guerra 2003; Talagrand 2006), ultrametricity (Panchenko 2013), uniqueness of the minimiser (Auffinger–Chen 2015) and infinitely many steps of RSB at zero temperature (Auffinger–Chen–Zeng 2020). The external-field transition is T020.",
 x="SOLVED: full replica symmetry breaking at zero external field for every β > 1 (P. Lopatto, arXiv:2607.11756, v4): the Parisi measure has support [0, q_β], a smooth density there and an atom at q_β. Zhou (arXiv:2504.00269) had covered temperatures slightly below the critical one. Read from the arXiv abstract 14 Oct; flagged by the w672 audit."),
dict(id="T052", d="SM", t="Uniqueness of the ground-state pair of the two-dimensional Edwards–Anderson spin glass",
 s="For the Edwards–Anderson spin glass on Z^2 with iid continuous couplings, every metastate built from boundary conditions independent of the couplings is supported on a single pair (σ, −σ) of infinite-volume ground states. The stronger statement, that almost surely there is only one such pair among all infinite-volume ground states, is a separate conjecture.",
 src="C. M. Newman and D. L. Stein, Ordering and broken symmetry in short-ranged spin glasses, J. Phys.: Condens. Matter 15 (2003); D. S. Fisher and D. A. Huse, Ordered phase of short-range Ising spin-glasses, Phys. Rev. Lett. 56 (1986)",
 why="The number of ground states is where the droplet and replica-symmetry-breaking pictures of short-range spin glasses first disagree, and two dimensions is the case where every method can be tried.",
 st="Proved (claimed): Newman and Stein (arXiv:2510.27507v2, October 2025, revised 2026) show that a critical droplet with space-filling boundary cannot occur in ground states generated by coupling-independent boundary conditions, deduce that incongruent ground states would have energy differences with variance of the order of the volume, and use this to prove that in two dimensions the metastate generated by, for example, periodic boundary conditions is unique and supported on a single pair of spin-reversed ground states (abstract read 14 Oct). Before that: uniqueness of the ground-state pair in the half-plane (Arguin–Damron–Newman–Stein 2010); a relation between disorder chaos and incongruent ground states in Z^d (Arguin–Newman–Stein, arXiv:1803.02308). The stronger statement, one pair among all infinite-volume ground states, and every higher dimension remain open.",
 x="SOLVED as stated (claim): Newman and Stein, arXiv:2510.27507v2 (revised 2026), prove that in two dimensions the metastate generated by coupling-independent boundary conditions, periodic ones being the example the abstract names, is unique and supported on a single pair of spin-reversed ground states (abstract read 14 Oct; flagged by w673). A preprint claim, not independently checked. The stronger all-ground-states statement is not claimed and is not listed separately."),
dict(id="T053", d="DYN", t="Diffusion in the random Lorentz gas at fixed density",
 s="A point particle moving at unit speed with specular reflection among fixed hard balls of radius r centred at the points of a Poisson process in R^d (d ≥ 2, fixed density and radius below the threshold at which the vacant set stops percolating, the particle started with a random direction in the unbounded component of the vacant set) behaves diffusively: X_t/√t converges to a non-degenerate Gaussian. In d = 2 the motion is recurrent.",
 c="Started anywhere outside the balls the statement is false: with positive probability the origin lies in a bounded vacant cavity and the particle stays bounded (w672 audit, 14 Oct). Annealed or quenched limit to be fixed.",
 src="H. A. Lorentz, The motion of electrons in metallic bodies, Proc. Amsterdam Acad. 7 (1905); H. Spohn, Large Scale Dynamics of Interacting Particles (Springer, 1991)",
 why="The simplest deterministic dynamics in a random medium; diffusion has been derived only through limits that make the scatterers sparse, and the fixed-density gas is the honest version of the question.",
 st="In the Boltzmann–Grad limit the motion becomes a Markov flight process (Gallavotti 1969; Spohn 1978; Boldrighini–Bunimovich–Sinai 1983); diffusion under a joint Boltzmann–Grad and diffusive scaling, past the kinetic time scale (Lutsko–Tóth, arXiv:1812.11325). Periodic scatterers: CLT with finite horizon (Bunimovich–Sinai 1981), √(t log t) with infinite horizon (Szász–Varjú 2007). Open at fixed density, including recurrence in d = 2."),
dict(id="T054", d="RMT", t="Bulk universality and quantum unique ergodicity for random regular graphs of fixed degree",
 s="For fixed d ≥ 3, the adjacency eigenvalues of a uniform random d-regular graph on N vertices have GOE local statistics in the bulk of the Kesten–McKay law as N → ∞, and the eigenvectors are delocalized and satisfy quantum unique ergodicity.",
 src="D. Jakobson, S. D. Miller, I. Rivin and Z. Rudnick, Eigenvalue spacings for regular graphs, in Emerging Applications of Number Theory (IMA Vol. 109, 1999)",
 why="The discrete analogue of the Bohigas–Giannoni–Schmit conjecture for chaotic billiards, for a model with no independent matrix entries and bounded degree.",
 st="Bulk GOE statistics for degree growing with N (Bauerschmidt–Huang–Knowles–Yau 2017, 2020); local Kesten–McKay law and delocalization for fixed large d (Bauerschmidt–Huang–Yau, arXiv:1609.09052); edge Tracy–Widom statistics and the Ramanujan property with probability about 0.69 for fixed d (Huang–McKenzie–Yau, arXiv:2412.20263). He–Huang–Wang (arXiv:2610.08127) prove Sine_1 bulk universality (point process, gaps and fixed-energy correlations) for every fixed d ≥ 3. Quantum unique ergodicity at fixed d is open. Update, 14 Nov 2026: bulk GOE statistics for every fixed d >= 3 are claimed by Y. He, J. Huang and X. Wang, Bulk universality of random regular graphs (arXiv:2610.08127), and by the AI-written OpenAI release preprint 'GOE bulk universality for fixed-degree random regular graphs' (23 Sep 2026); spatial quantum unique ergodicity at fixed degree remains open.",
 c="Bulk statistics at fixed d were proved in October 2026 (He–Huang–Wang, arXiv:2610.08127); the open part is quantum unique ergodicity, whose precise form (which observables, which rate) must be fixed before work on it."),
dict(id="T055", d="SM", t="Dimensional reduction for lattice trees and lattice animals",
 s="The critical exponents of lattice trees and lattice animals in Z^d equal those of the Yang–Lee edge singularity in dimension d − 2 (Parisi–Sourlas); in particular the number of lattice animals of size n grows like λ^n n^{−θ} with θ = 1 in d = 2 and θ = 3/2 in d = 3.",
 src="G. Parisi and N. Sourlas, Critical behavior of branched polymers and the Lee–Yang edge singularity, Phys. Rev. Lett. 46 (1981); D. C. Brydges and J. Z. Imbrie, Branched polymers and dimensional reduction, Ann. of Math. 158 (2003)",
 url="https://arxiv.org/abs/math-ph/0107005",
 why="A supersymmetry argument predicts exact exponents for branched polymers in low dimension; the continuum version is a theorem, and the lattice version would make it a fact about counting clusters.",
 st="Proved for a continuum model of branched polymers in d = 2, 3 (Brydges–Imbrie 2003). Lattice trees and animals are mean-field in high dimension (Hara–Slade 1990). Open for lattice models in d = 2, 3."),
dict(id="T056", d="DYN", t="Gaboriau's fixed price problem",
 s="Every countable group Γ has fixed price: all free probability-measure-preserving actions of Γ have the same cost.",
 src="D. Gaboriau, Coût des relations d'équivalence et des groupes, Invent. Math. 139 (2000)",
 why="Cost is the measured analogue of the rank of a group, and fixed price is the main open problem of measured group theory; it is tied to percolation and spanning forests on Cayley graphs (Lyons) and to rank gradient (Abért–Nikolov).",
 st="Fixed price holds for amenable groups (cost 1), free groups, and many classes closed under products and commensurability (Gaboriau 2000); higher-rank semisimple Lie groups and their lattices have fixed price 1 (Fraczyk–Mellick–Wilkens, arXiv:2307.01194, via Poisson–Voronoi tessellations). Open in general.",
 n="Fame borderline in the w672 audit (14 Oct); kept for now."),
dict(id="T057", d="RW", t="Is the Liouville property of a group independent of the generating set?",
 s="For a finitely generated group Γ, simple random walk on the Cayley graph Cay(Γ, S) has trivial Poisson boundary (no non-constant bounded harmonic functions) either for every finite symmetric generating set S or for none.",
 c="The analogue for quasi-isometric graphs is false (T. Lyons, J. Differential Geom. 26 (1987)), and for quasi-isometric groups as well (Erschler, Invent. Math. 155 (2004)); the question here is for one group with different generating sets.",
 src="V. A. Kaimanovich and A. M. Vershik, Random walks on discrete groups: boundary and entropy, Ann. Probab. 11 (1983)",
 why="Whether the Poisson boundary is a property of the group or of the walk is the basic question of the entropy theory of random walks on groups.",
 st="True for groups where every measure is Liouville (the Choquet–Deny groups, characterised by Frisch–Hartman–Tamuz–Vahidi Ferdowsi, arXiv:1802.00751) and for groups with no Liouville measure at all; lamplighter boundaries identified (Erschler; Lyons–Peres, arXiv:1508.01845). Gournay (arXiv:2602.00187) shows that the Liouville property passes to hyperrecurrent extensions for every measure whose support generates the group. Open in general."),
dict(id="T058", d="RG", t="Concentration of the chromatic number of G(n, 1/2)",
 s="Determine the width of concentration of χ(G(n, 1/2)): conjecturally, for a set of n of density one, the shortest interval containing χ(G(n, 1/2)) with probability tending to 1 has length n^{1/2+o(1)}.",
 c="The exact form of the conjecture (most n versus all n) is to verify.",
 src="E. Shamir and J. Spencer, Sharp concentration of the chromatic number on random graphs G_{n,p}, Combinatorica 7 (1987); B. Bollobás, How sharp is the concentration of the chromatic number?, Combin. Probab. Comput. 13 (2004); A. Heckel and O. Riordan, How does the chromatic number of a random graph vary?, J. London Math. Soc. 108 (2023) 1769–1815",
 why="Concentration of the chromatic number is a classical showcase of martingale methods; whether the √n window is the truth was open for thirty years.",
 st="Concentration on an interval of length about √n (Shamir–Spencer 1987); not concentrated on fewer than n^{1/4−ε} values for infinitely many n (Heckel, arXiv:1906.11808), improved to n^{1/2−ε} (Heckel–Riordan, J. Lond. Math. Soc. 108 (2023)). The behaviour for typical n is open."),
dict(id="T059", d="STAT", t="Robbins' problem: minimising the expected rank with full information",
 s="Observe iid Uniform(0, 1) values X_1, …, X_n one at a time, seeing their values; choose a stopping time τ to minimise the expected rank of X_τ among all n values. Determine V = lim V_n, and the form of an optimal rule.",
 src="F. T. Bruss and T. S. Ferguson, Minimizing the expected rank with full information, J. Appl. Probab. 30 (1993); F. T. Bruss, What is known about Robbins' problem?, J. Appl. Probab. 42 (2005)",
 why="The best-known open problem of optimal stopping: an innocent extension of the secretary problem whose optimal rule depends on the whole history.",
 st="The limit V exists and lies between 1.908 (Bruss–Ferguson 1993) and 2.32614 (Meier–Sögner, arXiv:1606.03348); memoryless threshold rules are not optimal (Bruss–Ferguson). Brice–Bruss–Majumdar–Raskin (arXiv:2608.27419) give near-optimal strategies and improved values for n = 5 to 100 through finite-state abstractions; exact values are known only for n ≤ 4. Goldenshluger and Malinovsky (arXiv:2610.33701) characterise the optimal rule for each n by dynamic-programming recursions and compute approximate values. The no-information version has value about 3.8695 (Chow–Moriguti–Robbins–Samuels 1964). V is unknown."),
dict(id="T060", d="SM", t="The Haldane conjecture for integer-spin chains",
 s="The spin-1 antiferromagnetic Heisenberg chain H = Σ_x S_x·S_{x+1} has a unique infinite-volume ground state, a spectral gap above it, and exponentially decaying correlations; more generally antiferromagnetic Heisenberg chains are gapped for integer spin and gapless for half-integer spin.",
 src="F. D. M. Haldane, Nonlinear field theory of large-spin Heisenberg antiferromagnets, Phys. Lett. A 93 (1983); F. D. M. Haldane, Continuum dynamics of the 1-D Heisenberg antiferromagnet, Phys. Rev. Lett. 50 (1983)",
 why="A Nobel-cited prediction about the simplest quantum many-body system; probabilists meet it through the loop representations of Tóth and Aizenman–Nachtergaele.",
 st="The AKLT chain, a different spin-1 Hamiltonian, is gapped (Affleck–Kennedy–Lieb–Tasaki 1987); half-integer chains cannot have a unique gapped ground state (Lieb–Schultz–Mattis 1961; Affleck–Lieb 1986); a loop-model reformulation (Aizenman–Nachtergaele 1994). Open for the spin-1 Heisenberg chain."),
dict(id="T061", d="COMB", t="Feige's 1/e conjecture and Samuels' conjecture",
 s="If X_1, …, X_n are independent nonnegative random variables each with mean at most 1 and S = X_1 + ⋯ + X_n, then P(S < E S + 1) ≥ 1/e, attained in the limit by X_i = (n + 1)·Bernoulli(1/(n + 1)). (Samuels' conjecture, which implies it, identifies the extremal laws for P(S ≥ a) given the means.)",
 c="Feige proves P(S < E S + 1) ≥ 1/13 and conjectures 1/e in that form; since E S ≤ n it implies the weaker P(S < n + 1) form, and the two agree when every mean is 1.",
 src="U. Feige, On sums of independent random variables with unbounded variance and estimating the average degree in a graph, SIAM J. Comput. 35 (2006); S. M. Samuels, On a Chebyshev-type inequality for sums of independent random variables, Ann. Math. Statist. 37 (1966)",
 why="A bound for sums with no variance assumption that appears in algorithm analysis; the constant 1/e would be sharp, and the known proofs reach less than a fifth.",
 st="Proved: Samuels' formula (Ling, arXiv:2608.18392), with Feige's 1/e as the equal-means case; a reformulation of the proof (Han, arXiv:2608.22816) and a short proof of Feige's bound (Milojević–Sudakov, arXiv:2610.10380). Before that: 1/13 (Feige), 1/8 (He–Zhang–Zhang 2010), about 0.14 (Garnett 2020), about 0.18 (Guo–He–Ling–Liu 2021); Samuels' conjecture for n ≤ 4 (Samuels 1966, 1968).",
 x="SOLVED: Samuels' conjecture is proved by Ling (arXiv:2608.18392), and Feige's 1/e bound follows from its equal-means case; Han (arXiv:2608.22816) recasts the proof as a cap-move argument and Milojević–Sudakov (arXiv:2610.10380) give a short proof of Feige's inequality. Read from the arXiv abstract 14 Oct; flagged by the w672 audit."),
dict(id="T062", d="GEOM", t="Sylvester's problem in dimension three and higher",
 s="For a convex body K ⊂ R^d let v(K) be the expected volume of the convex hull of d + 1 independent uniform points of K, divided by vol(K). For d ≥ 3, v(K) is maximised by the simplex.",
 src="W. Blaschke, Über affine Geometrie XI: Lösung des 'Vierpunktproblems' von Sylvester aus der Theorie der geometrischen Wahrscheinlichkeiten, Ber. Verh. Sächs. Akad. Leipzig 69 (1917); V. Klee, What is the expected volume of a simplex whose vertices are chosen at random from a given convex body?, Amer. Math. Monthly 76 (1969)",
 why="Sylvester's four-point problem is the founding question of geometric probability; the upper bound in high dimension is linked to the isotropic constant (Milman–Pajor).",
 st="d = 2 solved (Blaschke 1917: triangles maximise, ellipses minimise); ellipsoids minimise in every dimension (Groemer 1973); in the plane triangles also maximise for any number of points (Campi–Colesanti–Gronchi 1999, by shadow systems; cited in arXiv:1311.3690). The maximum is open for d ≥ 3."),
]
